import CoreFoundation
import Foundation

/// A document decoded against one named definition of the AG-UI 1.0 contract.
/// The original JSON tree is retained, including extension fields and opaque values.
public struct AGUISchemaDocument {
    public let definition: String
    public let value: Any
    public var fields: [String: Any] { value as? [String: Any] ?? [:] }
    private let originalData: Data?

    public init(_ data: Data, definition: String = "Event", allowUnknownFields: Bool = false) throws {
        let object = try JSONSerialization.jsonObject(with: data, options: [.fragmentsAllowed])
        guard let schema = Self.definitions[definition] else { throw AGUISchemaError.unknownDefinition(definition) }
        guard Self.accepts(object, schema: schema, allowUnknown: allowUnknownFields) else { throw AGUISchemaError.invalidValue(definition) }
        self.definition = definition
        self.value = object
        self.originalData = data
    }

    /// Accepts producer objects with explicit optional nulls, applying the SDK's
    /// omission rule before strict schema validation.
    public init(normalizing data: Data, definition: String = "Event") throws {
        guard let object = try JSONSerialization.jsonObject(with: data) as? [String: Any],
              let schema = Self.definitions[definition] else { throw AGUISchemaError.invalidJSON }
        let normalized = Self.normalize(object, schema: schema) as! [String: Any]
        guard Self.accepts(normalized, schema: schema) else { throw AGUISchemaError.invalidValue(definition) }
        self.definition = definition
        self.value = normalized
        self.originalData = nil
    }

    public func encoded() throws -> Data {
        if let originalData { return originalData }
        let object = Self.normalize(fields, schema: Self.definitions[definition]!) as! [String: Any]
        return try JSONSerialization.data(withJSONObject: object, options: [.sortedKeys, .fragmentsAllowed])
    }

    public func sseFrame() throws -> Data { Data("data: \(String(decoding: try encoded(), as: UTF8.self))\n\n".utf8) }

    private static let definitions: [String: [String: Any]] = {
        let data = Data(schemaJSON.utf8)
        return try! JSONSerialization.jsonObject(with: data) as! [String: [String: Any]]
    }()

    private static func normalize(_ value: Any, schema: [String: Any]) -> Any {
        if let ref = schema["$ref"] as? String,
           let target = definitions[String(ref.split(separator: "/").last ?? "")] {
            return normalize(value, schema: target)
        }
        if let one = schema["oneOf"] as? [[String: Any]] {
            for variant in one {
                let candidate = normalize(value, schema: variant)
                if accepts(candidate, schema: variant) { return candidate }
            }
        }
        guard let object = value as? [String: Any] else { return value }
        var properties = schema["properties"] as? [String: [String: Any]] ?? [:]
        var required = Set(schema["required"] as? [String] ?? [])
        for part in schema["allOf"] as? [[String: Any]] ?? [] {
            let source: [String: Any]
            if let ref = part["$ref"] as? String {
                source = definitions[String(ref.split(separator: "/").last ?? "")] ?? [:]
            } else { source = part }
            properties.merge(source["properties"] as? [String: [String: Any]] ?? [:]) { old, _ in old }
            required.formUnion(source["required"] as? [String] ?? [])
        }
        var result: [String: Any] = [:]
        for (key, field) in object {
            if field is NSNull && properties[key] != nil && !required.contains(key) { continue }
            result[key] = properties[key].map { normalize(field, schema: $0) } ?? field
        }
        return result
    }

    private static func accepts(_ value: Any, schema: [String: Any], allowUnknown: Bool = false) -> Bool {
        if let ref = schema["$ref"] as? String {
            let name = String(ref.split(separator: "/").last ?? "")
            guard let target = definitions[name], accepts(value, schema: target, allowUnknown: allowUnknown) else { return false }
        }
        if let constant = schema["const"], !equal(value, constant) { return false }
        if let choices = schema["enum"] as? [Any], !choices.contains(where: { equal(value, $0) }) { return false }
        if let all = schema["allOf"] as? [[String: Any]], !all.allSatisfy({ accepts(value, schema: $0, allowUnknown: allowUnknown) }) { return false }
        if let one = schema["oneOf"] as? [[String: Any]], one.filter({ accepts(value, schema: $0, allowUnknown: allowUnknown) }).count != 1 { return false }
        if let not = schema["not"] as? [String: Any], accepts(value, schema: not, allowUnknown: allowUnknown) { return false }
        if let type = schema["type"] as? String {
            switch type {
            case "object": guard value is [String: Any] else { return false }
            case "array": guard value is [Any] else { return false }
            case "string": guard value is String else { return false }
            case "null": guard value is NSNull else { return false }
            case "boolean": guard let n = value as? NSNumber, CFGetTypeID(n) == CFBooleanGetTypeID() else { return false }
            case "integer": guard let n = value as? NSNumber, CFGetTypeID(n) != CFBooleanGetTypeID(), n.decimalValue == NSDecimalNumber(decimal: n.decimalValue).rounding(accordingToBehavior: integerRounding).decimalValue else { return false }
            case "number": guard let n = value as? NSNumber, CFGetTypeID(n) != CFBooleanGetTypeID() else { return false }
            default: return false
            }
        }
        if let pattern = schema["pattern"] as? String, let string = value as? String,
           string.range(of: pattern, options: .regularExpression) == nil { return false }
        if let n = value as? NSNumber, CFGetTypeID(n) != CFBooleanGetTypeID() {
            if let minimum = schema["minimum"] as? NSNumber, n.decimalValue < minimum.decimalValue { return false }
            if let maximum = schema["maximum"] as? NSNumber, n.decimalValue > maximum.decimalValue { return false }
        }
        if let array = value as? [Any] {
            if let minimum = schema["minItems"] as? Int, array.count < minimum { return false }
            if let item = schema["items"] as? [String: Any], !array.allSatisfy({ accepts($0, schema: item, allowUnknown: allowUnknown) }) { return false }
        }
        if let object = value as? [String: Any] {
            for key in schema["required"] as? [String] ?? [] where object[key] == nil { return false }
            let properties = schema["properties"] as? [String: [String: Any]] ?? [:]
            for (key, item) in object {
                if let property = properties[key] {
                    if !accepts(item, schema: property, allowUnknown: allowUnknown) { return false }
                } else if let additional = schema["additionalProperties"] as? Bool, !additional && !allowUnknown {
                    return false
                } else if let additional = schema["additionalProperties"] as? [String: Any] {
                    if !accepts(item, schema: additional, allowUnknown: allowUnknown) { return false }
                } else if !allowUnknown && schema["unevaluatedProperties"] as? Bool == false && !knownKeys(schema).contains(key) {
                    return false
                }
            }
        }
        return true
    }

    private static let integerRounding = NSDecimalNumberHandler(roundingMode: .down, scale: 0, raiseOnExactness: false, raiseOnOverflow: false, raiseOnUnderflow: false, raiseOnDivideByZero: false)

    private static func equal(_ a: Any, _ b: Any) -> Bool {
        if let a = a as? String, let b = b as? String { return a == b }
        if let a = a as? NSNumber, let b = b as? NSNumber { return a == b }
        return false
    }

    private static func knownKeys(_ schema: [String: Any]) -> Set<String> {
        var keys = Set((schema["properties"] as? [String: Any] ?? [:]).keys)
        for part in schema["allOf"] as? [[String: Any]] ?? [] {
            keys.formUnion(knownKeys(part))
            if let ref = part["$ref"] as? String,
               let target = definitions[String(ref.split(separator: "/").last ?? "")] { keys.formUnion(knownKeys(target)) }
        }
        return keys
    }
}

